const svg = document.getElementById('plot-svg');
        const curve = document.getElementById('dist-curve');
        const barsGroup = document.getElementById('dist-bars');
        function updateUI() {
            const type = document.getElementById('dist-type').value;
            const p1 = document.getElementById('param-1');
            const p2 = document.getElementById('param-2');
            const l1 = document.getElementById('param-1-label');
            const l2 = document.getElementById('param-2-label');
            const wrap2 = document.getElementById('param-2-wrap');
            const badge = document.getElementById('type-badge');
            if (type === 'normal') {
                l1.innerText = "Mean (μ)"; l2.innerText = "Std Dev (σ)";
                p1.min = -10; p1.max = 10; p1.value = 0;
                p2.min = 0.1; p2.max = 5; p2.value = 1;
                wrap2.classList.remove('hidden');
                badge.innerText = "NORMAL DIST";
            } else if (type === 'binomial') {
                l1.innerText = "Trials (n)"; l2.innerText = "Prob (p)";
                p1.min = 1; p1.max = 50; p1.value = 20;
                p2.min = 0.01; p2.max = 0.99; p2.value = 0.5;
                wrap2.classList.remove('hidden');
                badge.innerText = "BINOMIAL DIST";
            } else {
                l1.innerText = "Lambda (λ)";
                p1.min = 0.1; p1.max = 20; p1.value = 5;
                wrap2.classList.add('hidden');
                badge.innerText = "POISSON DIST";
            }
            draw();
        }
        function draw() {
            const type = document.getElementById('dist-type').value;
            const val1 = parseFloat(document.getElementById('param-1').value);
            const val2 = parseFloat(document.getElementById('param-2').value);
            const entropyEl = document.getElementById('entropy-val');
            document.getElementById('param-1-val').innerText = val1;
            document.getElementById('param-2-val').innerText = val2;
            curve.setAttribute('d', '');
            barsGroup.innerHTML = '';
            if (type === 'normal') {
                drawNormal(val1, val2);
                // Entropy: ln(sigma * sqrt(2*pi*e))
                const ent = Math.log(val2 * Math.sqrt(2 * Math.PI * Math.E));
                entropyEl.innerText = ent.toFixed(3);
            } else if (type === 'binomial') {
                drawBinomial(val1, val2);
                // Entropy: approx 0.5 * ln(2 * pi * e * n * p * (1-p))
                const ent = 0.5 * Math.log(2 * Math.PI * Math.E * val1 * val2 * (1 - val2));
                entropyEl.innerText = Math.max(0, ent).toFixed(3);
            } else {
                drawPoisson(val1);
                // Entropy: approx 0.5 * ln(2 * pi * e * lambda)
                const ent = 0.5 * Math.log(2 * Math.PI * Math.E * val1);
                entropyEl.innerText = Math.max(0, ent).toFixed(3);
            }
        }
        function drawNormal(mu, sigma) {
            let points = [];
            // Scaling coordinates: 400x200 SVG box
            // Domain: -15 to +15 centered at 0
            for (let x = -15; x <= 15; x += 0.1) {
                const y = (1 / (sigma * Math.sqrt(2 * Math.PI))) * Math.exp(-0.5 * Math.pow((x - mu) / sigma, 2));
                const cx = (x + 15) * (400 / 30);
                const cy = 200 - (y * 450); // Scale Y factor
                points.push(`${cx},${cy}`);
            }
            curve.setAttribute('d', `M ${points.join(' L ')}`);
        }
        function drawBinomial(n, p) {
            const width = 400 / (n + 1);
            for (let k = 0; k <= n; k++) {
                const prob = nCr(n, k) * Math.pow(p, k) * Math.pow(1 - p, n - k);
                const h = prob * 400;
                const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
                rect.setAttribute("x", k * width);
                rect.setAttribute("y", 200 - h);
                rect.setAttribute("width", Math.max(1, width - 2));
                rect.setAttribute("height", h);
                rect.setAttribute("class", "bar-rect");
                barsGroup.appendChild(rect);
            }
        }
        function drawPoisson(lambda) {
            const width = 400 / 31;
            for (let k = 0; k <= 30; k++) {
                const prob = (Math.pow(lambda, k) * Math.exp(-lambda)) / factorial(k);
                const h = prob * 400;
                const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
                rect.setAttribute("x", k * width);
                rect.setAttribute("y", 200 - h);
                rect.setAttribute("width", width - 2);
                rect.setAttribute("height", h);
                rect.setAttribute("class", "bar-rect");
                barsGroup.appendChild(rect);
            }
        }
        function nCr(n, r) {
            if (r > n) return 0;
            if (r === 0 || r === n) return 1;
            if (r > n / 2) r = n - r;
            let res = 1;
            for (let i = 1; i <= r; i++) {
                res = res * (n - i + 1) / i;
            }
            return res;
        }
        function factorial(n) {
            if (n === 0) return 1;
            let res = 1;
            for (let i = 2; i <= n; i++) res *= i;
            return res;
        }
        window.onload = updateUI;
